/** The port `npm start` serves the app and its API on. */
export const LIFO_NEWS_PORT = 3000;

/**
 * The Lifo Cloud start command: tinbase in the background, then the app. The same command as in a
 * tab: in a cloud box the cloud sets DATABASE_URL to the box's own Postgres database (one Postgres
 * per account, next to its boxes), and tinbase runs on it, so posts survive the box sleeping. In a
 * tab tinbase runs on pg-mem, in memory. (`npm run db:disk` is still there for real Postgres
 * in a tab or on a machine, via PGlite.)
 */
export const LIFO_NEWS_START = "supabase start & npm start";

/** The app's files under `root` (an absolute path in the box). */
export function lifoNewsFiles(root: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [path, text] of Object.entries(LIFO_NEWS_FILES)) out[`${root}/${path}`] = text;
  return out;
}
